import React from "react";

const FractionDisplay = ({ numerator, denominator }) => {
  return (
    <div>
      <td className="first-col px-2 ">
        <table className="">
          <tbody className="">
            <tr className="">{numerator}</tr>
            <tr className="line-tr">
              <div className="line"></div>
            </tr>
            <tr>{denominator}</tr>
          </tbody>
        </table>
      </td>
    </div>
  );
};

export default FractionDisplay;
